    @Autowired
    private MockMvc mockMvc;

    @Test
    void reportDispatchAndEscalateOverHttp() throws Exception {
        mockMvc.perform(post("/api/elevators")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"code\":\"EL-API\"}"))
                .andExpect(status().isOk())
